pub fn all_characters_same(s: &[u8]) -> bool {
    // An empty slice or a single-element slice trivially has all identical bytes.
    if s.len() <= 1 {
        return true;
    }

    // Take the first byte as the reference.
    let first = s[0];
    // Check that every other byte matches the first one.
    for &b in &s[1..] {
        if b != first {
            return false;
        }
    }
    true
}

